"""Self-contained Library screen for the local web app."""
from __future__ import annotations


def _library_page_base() -> str:
    return '''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>کتابخانه | KALIMA</title><style>
:root{--bg:#f2f6fc;--surface:#ffffff;--surface-2:#f6f9fd;--ink:#17233a;--ink-2:#32415c;--muted:#75849c;--line:#e4ebf5;--line-2:#d4dfef;--brand:#356df6;--brand-2:#7257e8;--teal:#0ca6a6;--green:#0b9263;--red:#de4b4b;--amber:#c98a0b;--blue-soft:#eaf1ff;--green-soft:#e7f8f0;--red-soft:#fdecec;--amber-soft:#fdf4e1;--shadow-sm:0 4px 14px rgba(38,57,93,.05);--shadow:0 14px 36px rgba(38,57,93,.09);--shadow-lg:0 24px 56px rgba(38,57,93,.16);--ring:0 0 0 4px rgba(53,109,246,.18);--r-sm:10px;--r-md:14px;--r-lg:20px;--grad:linear-gradient(135deg,#356df6,#7257e8)}body.app-dark{--bg:#13161c;--surface:#1d2129;--surface-2:#242a36;--ink:#eae6dc;--ink-2:#cfcabf;--muted:#a09c94;--line:#30363f;--line-2:#3a414d;--blue-soft:#222c44;--green-soft:#14332a;--red-soft:#3b2326;--amber-soft:#3a2f19;--shadow-sm:0 4px 14px rgba(0,0,0,.28);--shadow:0 14px 36px rgba(0,0,0,.42);--shadow-lg:0 24px 56px rgba(0,0,0,.55)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:radial-gradient(1100px 520px at 88% -6%,#e6efff 0,transparent 60%),radial-gradient(900px 480px at 0% 108%,#e0f6ee 0,transparent 58%),var(--bg);color:var(--ink);font:14px/1.75 Vazirmatn,Segoe UI,Tahoma,sans-serif;font-synthesis:none;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;color-scheme:light}body.app-dark{background:radial-gradient(1100px 520px at 88% -6%,#1c2333 0,transparent 60%),radial-gradient(900px 480px at 0% 108%,#13241f 0,transparent 58%),var(--bg);color-scheme:dark}button{font-family:inherit}a{color:inherit}::selection{background:#356df633}.wrap{max-width:1260px;margin:0 auto;padding:36px 24px 72px}
.head{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin:4px 2px 24px;flex-wrap:wrap}.eyebrow{display:inline-flex;align-items:center;gap:8px;color:var(--brand);font-size:11px;font-weight:800}.eyebrow::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--grad);box-shadow:0 0 0 4px rgba(53,109,246,.14)}.head h1{margin:9px 0 0;font-size:29px;font-weight:800;letter-spacing:-.5px;line-height:1.3}.head p{margin:7px 0 0;color:var(--muted);font-size:13px}.actions{display:flex;gap:9px;flex-wrap:wrap}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--line);background:var(--surface);color:var(--ink-2);border-radius:var(--r-sm);padding:10px 15px;font:700 12px inherit;cursor:pointer;text-decoration:none;box-shadow:var(--shadow-sm);transition:transform .15s ease,box-shadow .15s ease,background .15s ease,border-color .15s ease,color .15s ease}.btn:hover{border-color:var(--line-2);box-shadow:var(--shadow);transform:translateY(-1px)}.btn.primary{background:var(--grad);border:0;color:#fff;box-shadow:0 10px 22px rgba(53,109,246,.28)}.btn.primary:hover{box-shadow:0 14px 28px rgba(53,109,246,.38)}.btn.ghost{background:transparent;box-shadow:none}.btn.danger{background:var(--red-soft);border-color:transparent;color:var(--red)}.btn.icon{width:40px;height:40px;padding:0;border-radius:12px;font-size:15px;flex:none}.btn.small{padding:8px 12px;font-size:11px}
button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:none;box-shadow:var(--ring)}
.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:20px;padding:12px;background:color-mix(in srgb,var(--surface) 88%,transparent);backdrop-filter:blur(10px);border:1px solid var(--line);border-radius:var(--r-lg);box-shadow:var(--shadow-sm)}.field{position:relative;display:flex;align-items:center}.field.search{flex:1 1 250px;min-width:230px}.field.search .field-icon{position:absolute;right:13px;color:var(--muted);font-size:15px;pointer-events:none;line-height:0}.field.search input{width:100%;padding:11px 40px 11px 36px;border:1px solid var(--line);background:var(--surface-2);border-radius:var(--r-sm);font:inherit;color:var(--ink);transition:border-color .15s ease,box-shadow .15s ease,background .15s ease}.field.search input::placeholder{color:var(--muted);opacity:.85}.field.search input:focus{outline:none;border-color:var(--brand);box-shadow:var(--ring);background:var(--surface)}.field .clear{position:absolute;left:9px;width:22px;height:22px;border:0;border-radius:7px;background:#e6ebf5;color:var(--muted);font-size:11px;line-height:1;cursor:pointer;display:grid;place-items:center;padding:0}.field .clear:hover{background:#d9e1f0;color:var(--ink)}body.app-dark .field .clear{background:#313846;color:#aeb6c4}body.app-dark .field .clear:hover{background:#3b4354;color:#eae6dc}.field select{appearance:none;-webkit-appearance:none;padding:11px 14px 11px 34px;border:1px solid var(--line);background:var(--surface-2);border-radius:var(--r-sm);font:700 12px inherit;color:var(--ink-2);cursor:pointer;min-width:128px;transition:border-color .15s ease,box-shadow .15s ease}.field select:focus{outline:none;border-color:var(--brand);box-shadow:var(--ring)}.field .chev{position:absolute;left:12px;color:var(--muted);pointer-events:none;font-size:10px}
.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:22px}.stat{display:flex;align-items:center;gap:13px;padding:14px 16px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r-md);box-shadow:var(--shadow-sm);transition:box-shadow .15s ease,transform .15s ease}.stat:hover{box-shadow:var(--shadow);transform:translateY(-1px)}.stat-ic{width:42px;height:42px;flex:none;border-radius:12px;display:grid;place-items:center;font-size:19px;color:var(--brand);background:var(--blue-soft)}.stat:nth-child(2) .stat-ic{color:var(--teal);background:var(--green-soft)}.stat:nth-child(3) .stat-ic{color:var(--brand-2);background:#f0edff}.stat strong{display:block;font-size:19px;font-weight:800;line-height:1.25;font-variant-numeric:tabular-nums}.stat small{color:var(--muted);font-size:11.5px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(272px,1fr));gap:18px;align-items:stretch}.grid.list{grid-template-columns:1fr}
.book{position:relative;display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--line);border-radius:var(--r-lg);box-shadow:var(--shadow-sm);overflow:hidden;transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;animation:card-in .5s cubic-bezier(.2,.7,.3,1) both;animation-delay:calc(var(--i,0)*40ms)}.book:hover{transform:translateY(-4px);border-color:var(--line-2);box-shadow:var(--shadow-lg)}@keyframes card-in{from{opacity:0;transform:translateY(14px) scale(.98)}to{opacity:1;transform:none}}
.cover{position:relative;height:126px;display:grid;place-items:center;overflow:hidden}.cover::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(-55deg,rgba(255,255,255,.2) 0 14px,transparent 14px 28px);opacity:.5;mix-blend-mode:soft-light;pointer-events:none}.cover-glyph{position:relative;z-index:1;font-size:48px;font-weight:800;color:#fff;text-shadow:0 8px 22px rgba(23,35,56,.28);line-height:1}.cover-ext{position:absolute;top:12px;right:12px;background:rgba(20,30,50,.32);color:#fff;font-size:10px;font-weight:800;letter-spacing:.7px;padding:5px 10px;border-radius:999px;backdrop-filter:blur(5px);z-index:2}.cover-v{position:absolute;bottom:12px;left:12px;background:rgba(255,255,255,.22);border:1px solid rgba(255,255,255,.38);color:#fff;font-size:10px;font-weight:700;padding:4px 10px;border-radius:999px;backdrop-filter:blur(5px);z-index:2}.cover-completed{background:linear-gradient(140deg,#0f9e7c,#17bfa6)}.cover-running{background:linear-gradient(140deg,#3b6ef5,#7257e8)}.cover-failed{background:linear-gradient(140deg,#e05050,#bd4f8b)}.cover-available{background:linear-gradient(140deg,#0b8fc6,#17bfa6)}.cover-archived{background:linear-gradient(140deg,#6d7889,#93a0b2)}.grid.list .cover{width:160px;height:auto;min-height:150px;flex:none}.grid.list .cover-v{display:none}
.book-body{padding:16px;display:flex;flex-direction:column;gap:11px;flex:1;min-width:0}.book-title{font-size:15.5px;font-weight:800;line-height:1.65;color:var(--ink);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:calc(1.65em*2)}.book-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;color:var(--muted);font-size:11px}.book-meta b{color:var(--ink-2);font-weight:800}.badge-row{display:flex;align-items:center;gap:8px;margin-top:2px}.badge{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 11px;background:var(--blue-soft);color:var(--brand);font-size:11px;font-weight:800}.badge i{width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.85}.badge.running{background:var(--blue-soft);color:var(--brand)}.badge.completed{background:var(--green-soft);color:var(--green)}.badge.available{background:var(--green-soft);color:var(--teal)}.badge.failed{background:var(--red-soft);color:var(--red)}.badge.archived{background:#eef1f6;color:var(--muted)}body.app-dark .badge.archived{background:#2a303b;color:var(--muted)}.pct{margin-inline-start:auto;font-size:11px;font-weight:800;color:var(--ink-2);font-variant-numeric:tabular-nums}
.progress{height:7px;border-radius:99px;background:var(--surface-2);border:1px solid var(--line);overflow:hidden;position:relative}.progress i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--brand),var(--brand-2));position:relative;overflow:hidden;transition:width .4s ease}.progress i::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 32%,rgba(255,255,255,.5) 50%,transparent 68%);transform:translateX(-100%);animation:shine 2.4s ease infinite}@keyframes shine{to{transform:translateX(100%)}}
.book-actions{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:auto;padding-top:13px;border-top:1px solid var(--line)}.btn-sm{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--surface-2);color:var(--ink-2);border-radius:9px;padding:7px 11px;font:700 11px inherit;line-height:1;text-decoration:none;cursor:pointer;transition:background .15s ease,border-color .15s ease,color .15s ease,transform .15s ease,box-shadow .15s ease}.book-actions>a,.book-actions>button{gap:6px;border:1px solid var(--line);background:var(--surface-2);color:var(--ink-2);border-radius:9px;padding:7px 11px;font:700 11px inherit;line-height:1;text-decoration:none;cursor:pointer;transition:background .15s ease,border-color .15s ease,color .15s ease,transform .15s ease,box-shadow .15s ease}.btn-sm:hover,.book-actions>a:hover,.book-actions>button:hover{background:var(--blue-soft);border-color:#c9d9fb;color:var(--brand);transform:translateY(-1px)}.btn-sm.study{background:linear-gradient(135deg,#0b9263,#12b5a4);border:0;color:#fff;box-shadow:0 8px 18px rgba(11,146,99,.26)}.btn-sm.study:hover{background:linear-gradient(135deg,#0a8158,#10a290);color:#fff;box-shadow:0 10px 22px rgba(11,146,99,.34)}.btn-sm.danger,.book-actions>button.danger{background:var(--red-soft);border-color:transparent;color:var(--red)}.btn-sm.danger:hover,.book-actions>button.danger:hover{background:#fbdddd;color:var(--red);border-color:transparent}.book-actions>button:last-child{background:var(--red-soft);border-color:transparent;color:var(--red)}.book-actions>button:last-child:hover{background:#fbdddd;color:var(--red)}
.book-actions .dl-menu{position:relative;display:inline-block}.dl-menu summary{list-style:none}.dl-menu summary::-webkit-details-marker{display:none}.dl-caret{display:inline-block;transition:transform .15s ease}.dl-menu[open] .dl-caret{transform:rotate(180deg)}.dl-list{position:absolute;top:calc(100% + 6px);right:0;z-index:20;min-width:190px;background:var(--surface);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow-lg);padding:6px;display:grid;gap:3px;animation:card-in .16s ease both}.dl-list a{display:flex;align-items:center;gap:8px;font-size:11px;padding:8px 11px;border-radius:8px;background:var(--surface-2);color:var(--ink-2);white-space:nowrap;text-decoration:none}.dl-list a:hover{background:var(--blue-soft);color:var(--brand)}
.empty{padding:66px 26px;text-align:center;grid-column:1/-1;color:var(--muted);background:var(--surface);border:1.5px dashed var(--line-2);border-radius:var(--r-lg)}.empty-art{width:76px;height:76px;margin:0 auto 18px;border-radius:24px;display:grid;place-items:center;font-size:34px;color:#fff;background:var(--grad);box-shadow:0 16px 34px rgba(53,109,246,.3)}.empty strong{display:block;color:var(--ink);font-size:16px;margin-bottom:7px}.empty p{margin:0 0 20px;font-size:12.5px;line-height:1.9}
.skeleton .cover{background:linear-gradient(140deg,#e7edf6,#dce5f1)}.skeleton .line{height:12px;border-radius:6px;background:linear-gradient(90deg,#e7edf6,#d9e2f0);margin:12px 16px 0;position:relative;overflow:hidden}.skeleton .cover::after,.skeleton .line::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,transparent 30%,rgba(255,255,255,.8) 50%,transparent 70%);transform:translateX(-100%);animation:shine 1.5s ease infinite}body.app-dark .skeleton .cover{background:linear-gradient(140deg,#242a36,#2a313e)}body.app-dark .skeleton .line{background:linear-gradient(90deg,#242a36,#2b323f)}
.drawer{position:fixed;inset:0;background:rgba(13,21,38,.44);backdrop-filter:blur(4px);display:none;z-index:40}.drawer.open{display:block}.panel{position:absolute;right:0;top:0;bottom:0;width:min(480px,96vw);background:var(--surface);padding:26px;overflow:auto;box-shadow:var(--shadow-lg);display:flex;flex-direction:column;gap:18px;animation:slide-in .3s cubic-bezier(.2,.7,.3,1) both}@keyframes slide-in{from{transform:translateX(70px);opacity:0}to{transform:none;opacity:1}}.panel-head{display:flex;align-items:flex-start;gap:14px;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:16px}.panel-head h2{margin:0;font-size:19px;font-weight:800;line-height:1.65;word-break:break-word}.panel-meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.chip{display:inline-flex;align-items:center;gap:6px;background:var(--surface-2);border:1px solid var(--line);border-radius:999px;padding:5px 11px;font-size:11px;font-weight:700;color:var(--ink-2)}.variant{display:flex;align-items:center;gap:14px;padding:14px;border:1px solid var(--line);border-radius:var(--r-md);background:var(--surface-2);transition:border-color .15s ease,box-shadow .15s ease}.variant:hover{border-color:var(--line-2);box-shadow:var(--shadow-sm)}.variant+.variant{margin-top:10px}.variant-ic{width:44px;height:44px;flex:none;border-radius:13px;display:grid;place-items:center;font-weight:800;font-size:14px;color:var(--brand);background:var(--blue-soft)}.variant-ic.tr{color:var(--green);background:var(--green-soft)}.variant-main{flex:1;min-width:0}.variant-main strong{display:block;font-size:13px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.variant .note{color:var(--muted);font-size:11px;display:block;margin-top:4px;line-height:1.7}.variant-dl{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.dl-chip{display:inline-flex;align-items:center;gap:5px;background:var(--blue-soft);color:var(--brand);font-size:11px;font-weight:800;padding:6px 10px;border-radius:8px;text-decoration:none;border:1px solid transparent;transition:background .15s ease,transform .15s ease}.dl-chip:hover{background:#d9e5ff;transform:translateY(-1px)}.panel-foot{display:flex;gap:9px;justify-content:flex-end;border-top:1px solid var(--line);padding-top:18px}
@media(max-width:860px){.stats{grid-template-columns:1fr 1fr}.grid.list .book{flex-direction:column}.grid.list .cover{width:auto;height:110px;min-height:0}}@media(max-width:640px){.wrap{padding:24px 14px 64px}.head h1{font-size:24px}.toolbar{padding:10px}.field.search{min-width:100%}.field select{flex:1}.stats{grid-template-columns:1fr}.panel{width:100%}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style></head><body><main class="wrap"><header class="head"><div><span class="eyebrow">مرکز مطالعه و نگهداری</span><h1>کتابخانه</h1><p>مرکز نگهداری و مطالعهٔ کتاب‌های اصلی و ترجمه‌شده</p></div><div class="actions"><a class="btn" href="/">بازگشت به داشبورد</a><button class="btn primary" onclick="location.href='/'">ترجمهٔ جدید</button></div></header><div class="toolbar"><div class="field search"><span class="field-icon">⌕</span><input id="q" placeholder="جست‌وجوی نام کتاب…" aria-label="جست‌وجو" autocomplete="off" spellcheck="false"><button class="clear" id="clear-q" hidden aria-label="پاک کردن">✕</button></div><div class="field"><select id="status" aria-label="وضعیت"><option value="">همهٔ وضعیت‌ها</option><option value="completed">تکمیل‌شده</option><option value="running">در حال ترجمه</option><option value="failed">خطادار</option><option value="available">فایل اصلی</option></select><span class="chev">▾</span></div><div class="field"><select id="type" aria-label="فرمت"><option value="">همهٔ فرمت‌ها</option><option value="epub">EPUB</option><option value="pdf">PDF</option></select><span class="chev">▾</span></div><button class="btn small" id="view"><span>▧</span><span id="view-label">نمایش فهرستی</span></button></div><div class="stats" aria-live="polite"><div class="stat"><span class="stat-ic">▣</span><div><strong id="count">۰</strong><small>کتاب‌ها</small></div></div><div class="stat"><span class="stat-ic">⊕</span><div><strong id="used">۰ MB</strong><small>حجم کتابخانه</small></div></div><div class="stat"><span class="stat-ic">◉</span><div><strong id="free">—</strong><small>فضای آزاد</small></div></div></div><section id="grid" class="grid" aria-live="polite"></section></main><div class="drawer" id="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><aside class="panel"><div class="panel-head"><div><h2 id="detail-title"></h2><div class="panel-meta"><span class="chip" id="detail-meta"></span></div></div><button class="btn icon" id="close" aria-label="بستن">✕</button></div><div id="variants"></div><div class="panel-foot"><button class="btn danger" id="panel-delete">حذف این کتاب</button></div></aside></div><script>
const $=s=>document.querySelector(s),fa=n=>new Intl.NumberFormat('fa-IR').format(n||0),bytes=n=>n>1073741824?(n/1073741824).toFixed(1)+' GB':(n/1048576).toFixed(1)+' MB';let list=[],listMode=false,current=null;const STATUS_LABEL={completed:'تکمیل‌شده',running:'در حال ترجمه',failed:'خطادار',available:'فایل اصلی',archived:'آرشیوشده'};function params(){const p=new URLSearchParams();if($('#q').value.trim())p.set('q',$('#q').value.trim());if($('#status').value)p.set('status',$('#status').value);if($('#type').value)p.set('type',$('#type').value);return p}function fmtName(n){return ({'main':'سند اصلی','json_segments':'JSON_SEGMENTS','txt_bilingual':'TXT_BILINGUAL','markdown':'MARKDOWN','docx':'DOCX','translated_pdf':'PDF ترجمه‌شده','bilingual_pdf':'PDF دوزبانه','translated_epub':'EPUB','srt':'SRT','quality_report':'گزارش کیفیت'}[n]||n).toUpperCase()}function dlMenu(v){if(!v||!v.download)return '';const versions=v.versions||[];if(!versions.length)return `<a class="btn-sm" href="${v.download}">دانلود</a>`;return `<details class="dl-menu"><summary class="btn-sm">دانلود <span class="dl-caret">▾</span></summary><div class="dl-list">${versions.map(x=>`<a href="${x.download}">${fmtName(x.name)}</a>`).join('')}</div></details>`}function card(b,i){const translated=b.variants.find(v=>v.kind==='translated'),original=b.variants.find(v=>v.kind==='original'),v=translated||original,p=v&&v.progress&&v.progress.total?Math.round(v.progress.completed*100/v.progress.total):(b.status==='completed'?100:0),ext=(v?.extension||'FILE').toUpperCase();return `<article class="book" style="--i:${i%12}"><div class="cover cover-${b.status}"><span class="cover-glyph">${b.translated?'文':'▣'}</span><span class="cover-ext">${ext}</span><span class="cover-v">${b.variants.length} نسخه</span></div><div class="book-body"><div class="book-title" title="${b.title}">${b.title}</div><div class="book-meta"><b>${ext}</b><span>·</span><span>${bytes(b.size_bytes)}</span>${b.author?`<span>·</span><span>${b.author}</span>`:''}</div><div class="badge-row"><span class="badge ${b.status}"><i></i>${STATUS_LABEL[b.status]||b.status}</span>${p&&p<100?`<span class="pct">${p}٪</span>`:''}</div>${p&&p<100?`<div class="progress"><i style="width:${p}%"></i></div>`:''}<div class="book-actions">${translated?.reader?`<a class="btn-sm study" href="${translated.reader}">مطالعه</a>`:''}${dlMenu(translated)}<button data-detail="${b.id}">جزئیات</button><button data-delete="${b.id}">حذف</button></div></div></article>`}function emptyHTML(){return `<div class="empty"><div class="empty-art">▣</div><strong>${list.length?'کتابی در این بخش پیدا نشد.':'کتابی در کتابخانه ثبت نشده است.'}</strong><p>${list.length?'فیلترها را تغییر دهید و دوباره جست‌وجو کنید.':'اولین کتاب EPUB یا PDF را ترجمه کنید تا اینجا نمایش داده شود.'}</p><a class="btn primary" href="/">ترجمهٔ جدید</a></div>`}async function load(){$('#grid').innerHTML=Array.from({length:6},(_,i)=>`<article class="book skeleton" style="--i:${i}"><div class="cover"></div><div class="line" style="width:${62+i*6}%"></div><div class="line" style="width:38%"></div></article>`).join('');try{const d=await (await fetch('/api/library?'+params())).json();list=d.items||[];$('#count').textContent=fa(d.total);$('#used').textContent=bytes(d.storage?.used);$('#free').textContent=bytes(d.storage?.free);$('#clear-q').hidden=!$('#q').value;$('#grid').innerHTML=list.length?list.map(card).join(''):emptyHTML();document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.detail)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeBook(Number(b.dataset.delete)))}catch(err){$('#grid').innerHTML='<div class="empty"><div class="empty-art">!</div><strong>خطایی رخ داد</strong><p>دریافت فهرست کتابخانه ناموفق بود؛ دوباره تلاش کنید.</p></div>'}}function detail(id){const b=list.find(x=>x.id===id);if(!b)return;current=b;$('#detail-title').textContent=b.title;$('#detail-meta').textContent=`${b.variants.length} نسخه · ${bytes(b.size_bytes)} · آخرین فعالیت ${new Date(b.updated_at).toLocaleString('fa-IR')}`;$('#variants').innerHTML=b.variants.map(v=>{const pct=v.progress&&v.progress.total?Math.round(v.progress.completed*100/v.progress.total):null;const items=(v.versions&&v.versions.length?v.versions:[v.download?{name:v.kind==='translated'?'translated_epub':'main',download:v.download}:null]).filter(Boolean);return `<div class="variant"><div class="variant-ic ${v.kind==='translated'?'tr':''}">${v.kind==='translated'?'文':'▣'}</div><div class="variant-main"><strong>${v.kind==='translated'?'ترجمه‌شده':'نسخهٔ اصلی'} · ${(v.extension||'FILE').toUpperCase()}</strong><span class="note">${bytes(v.size_bytes)} · ${STATUS_LABEL[v.status]||v.status}${pct!=null?` · ${pct}٪`:''}${v.language?' · '+v.language:''}</span>${items.length?`<div class="variant-dl">${items.map(x=>`<a class="dl-chip" href="${x.download}">دانلود ${fmtName(x.name)}</a>`).join('')}</div>`:''}</div>${v.reader?`<a class="btn-sm study" href="${v.reader}">مطالعه</a>`:''}</div>`}).join('');$('#drawer').classList.add('open')}async function removeBook(id){if(!confirm('این کتاب و فایل‌های مرتبط حذف شوند؟'))return;const r=await fetch('/api/library/'+id,{method:'DELETE'});if(!r.ok){alert((await r.json()).error||'حذف انجام نشد');return}if(current&&current.id===id){current=null;$('#drawer').classList.remove('open')}load()}let debounce;$('#q').addEventListener('input',()=>{$('#clear-q').hidden=!$('#q').value;clearTimeout(debounce);debounce=setTimeout(load,260)});$('#clear-q').onclick=()=>{$('#q').value='';$('#clear-q').hidden=true;load()};$('#status').addEventListener('change',load);$('#type').addEventListener('change',load);$('#view').onclick=()=>{listMode=!listMode;$('#grid').classList.toggle('list',listMode);$('#view-label').textContent=listMode?'نمایش فهرستی':'نمایش شبکه‌ای'};$('#close').onclick=()=>{$('#drawer').classList.remove('open');current=null};$('#drawer').onclick=e=>{if(e.target.id==='drawer'){$('#drawer').classList.remove('open');current=null}};$('#panel-delete').onclick=()=>{if(current)removeBook(current.id)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#drawer').classList.remove('open');current=null}});load();</script></body></html>'''